  function addLog(icon,title,message){const log=$('activityLog');const item=document.createElement('div');item.className='log-entry';const s=document.createElement('span');s.textContent=icon;const p=document.createElement('p');const b=document.createElement('b');b.textContent=title;p.append(b,document.createElement('br'),document.createTextNode(message));item.append(s,p);log.prepend(item);while(log.children.length>6)log.lastElementChild.remove()}
