  function getEvent(){const day=Math.floor(Date.now()/86400000);const events=[{name:'The Fracture Tide',description:'Anomaly creatures appear near the old observatory.',status:'ACTIVE · BONUS ESSENCE',cycle:'TIDE I',bonus:'Essence surges through the region.'},{name:'Whispers in Glass',description:'Echo fragments are unusually easy to find.',status:'ACTIVE · ECHO HUNT',cycle:'TIDE II',bonus:'Echoes yield extra shards.'},{name:'The Hollow Moon',description:'Elite anomalies grow restless under the pale moon.',status:'ACTIVE · ELITE SURGE',cycle:'TIDE III',bonus:'Elite enemies offer bonus experience.'}];return events[day%events.length]}
  function applyEventUI(){const ev=getEvent();$('eventName').textContent=ev.name;$('eventDescription').textContent=ev.description;$('eventStatus').textContent=ev.status;$('cycleText').textContent=ev.cycle;$('eventTimer').textContent='ROTATES DAILY';if(state.lastEventDay!==dateKey){state.lastEventDay=dateKey;addLog('☄','World pulse',ev.name+' has begun.');}}
  function unlockChapterThree(logUnlock=true){
    state.flags=state.flags||{};
    if(state.flags.authorUnlocked && state.quest && !['city-complete','city-boss','city-return','city-shards','city-arrival'].includes(state.quest.id)) return;
    state.flags.authorUnlocked=true;
    state.activeZone='author-archive';
    state.player.x=280; state.player.y=300; state.player.moveTarget=null;
    state.flags.authorSigils=Array.isArray(state.flags.authorSigils)?state.flags.authorSigils:[];
    state.worldState='THE ARCHIVE REMEMBERED';
    state.quest={id:'author-arrival',title:'Chapter III: The Author’s Name',description:'Enter the Archive at the End and find the Blind Scribe.',count:0,goal:1,complete:false,claimed:false};
    state.enemies=[]; state.interactables=[]; state.target=null;
    seedWorld(); updateUI(); saveGame();
    if(logUnlock){addLog('✦','Chapter III unlocked','The Archive at the End has opened. Follow the quest marker to the Blind Scribe.');toast('CHAPTER III UNLOCKED · THE AUTHOR’S NAME');}
  }
  function loadSave(){try{const raw=localStorage.getItem('echoes_unwritten_save_v1');if(!raw)return;const saved=JSON.parse(raw);if(saved&&(saved.version===1||saved.version===2||saved.version===3||saved.version===4||saved.version===5||saved.version===6||saved.version===7)){Object.assign(state,saved.state); state.version=7; state.skillBuilds=Object.assign({},saved.state.skillBuilds||{}); state.skillRanks=Object.assign(defaultSkillRanks(),state.skillBuilds[state.className]||saved.state.skillRanks||{}); state.skillBuilds[state.className]=state.skillRanks; state.skillPoints=Number.isFinite(saved.state.skillPoints)?saved.state.skillPoints:Math.max(1,(state.level||1)-1); state.activeZone=state.activeZone||'shiverwild'; state.classChosen=state.classChosen!==false;state.player=Object.assign({x:900,y:700,r:16,speed:230,faceX:1,faceY:0,invuln:0,attack:0,slash:0,trail:[],moveTarget:null},saved.state.player||{});state.camera={x:0,y:0};state.navigation=null;state.flags=Object.assign({intro:false,archivist:false,bossSpawned:false,bossDefeated:false,cityUnlocked:false,cityShards:[],cityBossSpawned:false,cityBossDefeated:false,authorUnlocked:false,authorBossSpawned:false,authorBossDefeated:false,authorSigils:[],firstLoot:false,usedObjects:[]},state.flags||{});state.flags.usedObjects=Array.isArray(state.flags.usedObjects)?state.flags.usedObjects:[];if(state.flags.bossDefeated&&state.quest?.id==='last-margin'){state.activeZone='forgotten-city';state.flags.cityUnlocked=true;state.quest={id:'city-arrival',title:'The City That Forgot Tomorrow',description:'Follow the signal into the erased city and find the Clockmaker.',count:0,goal:1,complete:false,claimed:false};state.player.x=320;state.player.y=300;}if(state.flags.cityBossDefeated&&!state.flags.authorUnlocked&&['city-complete','city-boss','city-return','city-shards','city-arrival'].includes(state.quest?.id)){unlockChapterThree(false);}state.enemies=[];state.particles=[];state.floats=[];state.interactables=[];state.target=null;state.cooldowns=Object.assign({q:0,e:0,r:0},state.cooldowns||{});}}catch(e){console.warn('Save could not be loaded',e)}}
  function saveGame(){try{state.skillBuilds=state.skillBuilds||{};state.skillBuilds[state.className]=state.skillRanks||defaultSkillRanks();const copy={...state,enemies:undefined,particles:undefined,floats:undefined,interactables:undefined,target:undefined,camera:undefined,dialogueQueue:undefined,currentDialogue:undefined};localStorage.setItem('echoes_unwritten_save_v1',JSON.stringify({version:7,state:copy}));$('syncState').textContent='SAVED';$('syncState').style.color='var(--green)';$('saveIndicator')?.classList.add('saved');state.lastSaved=Date.now();}catch(e){$('syncState').textContent='OFFLINE'}}
  function resetNewGame(){state.name='Riven, the Unwritten';state.className='Riftblade';state.level=1;state.xp=0;state.xpNext=100;state.maxHp=100;state.hp=100;state.maxMp=60;state.mp=60;state.damage=18;state.shards=25;state.gearScore=12;state.player={x:900,y:700,r:16,speed:230,faceX:1,faceY:0,invuln:0,attack:0,slash:0,trail:[],moveTarget:null};state.navigation=null;state.activeZone='shiverwild';state.classChosen=true;state.quest={id:'echoes',title:'A Voice in the Static',description:'Find the three lost echoes scattered across the Shiverwild Verge.',count:0,goal:3,complete:false,claimed:false};state.flags={intro:false,archivist:false,bossSpawned:false,bossDefeated:false,cityUnlocked:false,cityShards:[],cityBossSpawned:false,cityBossDefeated:false,authorUnlocked:false,authorBossSpawned:false,authorBossDefeated:false,authorSigils:[],firstLoot:false,usedObjects:[]};state.inventory=[];state.equipment={weapon:null,armor:null,relic:null};state.skills={q:0,e:0,r:0};state.skillRanks=defaultSkillRanks();state.skillBuilds={Riftblade:state.skillRanks};state.skillPoints=1;state.defeated=0;state.worldState='UNSTABLE';seedWorld();updateUI();saveGame()}
  loadSave(); seedWorld();
