  function movePlayer(dt){const p=state.player;let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup'))dy--;if(keys.has('s')||keys.has('arrowdown'))dy++;if(keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;dx+=touchMove.x;dy+=touchMove.y;let l=Math.hypot(dx,dy);if(l>0.08){p.moveTarget=null;dx/=l;dy/=l;}else if(p.moveTarget){const mx=p.moveTarget.x-p.x,my=p.moveTarget.y-p.y,ml=Math.hypot(mx,my);if(ml<8){p.vx=0;p.vy=0;if(p.moveTarget.interact)p.pendingInteract=true;p.moveTarget=null;dx=0;dy=0;}else{dx=mx/ml;dy=my/ml;l=1;}}if(l>0.08){const moveSpeed=p.speed*(p.speedBuff>0?1.25:1);p.vx=dx*moveSpeed;p.vy=dy*moveSpeed;p.x=clamp(p.x+dx*moveSpeed*dt,35,WORLD.w-35);p.y=clamp(p.y+dy*moveSpeed*dt,35,WORLD.h-35);p.faceX=dx;p.faceY=dy;p.trail.push({x:p.x,y:p.y,t:.18});if(p.trail.length>12)p.trail.shift()}if(l<=0.08&&!p.moveTarget){p.vx=0;p.vy=0;}for(const t of p.trail)t.t-=dt;p.trail=p.trail.filter(t=>t.t>0);p.invuln=Math.max(0,p.invuln-dt);p.attack=Math.max(0,p.attack-dt);p.castTimer=Math.max(0,(p.castTimer||0)-dt);p.hitTimer=Math.max(0,(p.hitTimer||0)-dt);p.spiritWard=Math.max(0,(p.spiritWard||0)-dt*.2);p.speedBuff=Math.max(0,(p.speedBuff||0)-dt);p.slash=Math.max(0,p.slash-dt);state.mp=Math.min(state.maxMp,state.mp+dt*2.2);for(const k of Object.keys(state.cooldowns))state.cooldowns[k]=Math.max(0,state.cooldowns[k]-dt);}
  const touchMove={x:0,y:0};let joyActive=false,joyCenter=null;
  const joy=$('joystick'),knob=joy.querySelector('.joy-knob');function setJoy(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy;const max=29,l=Math.hypot(dx,dy)||1;if(l>max){dx=dx/l*max;dy=dy/l*max}touchMove.x=dx/max;touchMove.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}joy.addEventListener('pointerdown',e=>{joyActive=true;joy.setPointerCapture(e.pointerId);setJoy(e)});joy.addEventListener('pointermove',e=>{if(joyActive)setJoy(e)});function releaseJoy(){joyActive=false;touchMove.x=0;touchMove.y=0;knob.style.transform='translate(0,0)'}joy.addEventListener('pointerup',releaseJoy);joy.addEventListener('pointercancel',releaseJoy);
