  function drawPlayer(){const p=state.player;for(const t of p.trail){ctx.globalAlpha=t.t/.18*.2;ctx.fillStyle='#a99aff';ctx.beginPath();ctx.arc(t.x,t.y,10,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.save();ctx.translate(p.x,p.y);if(p.invuln>0&&Math.floor(state.tick*22)%2===0)ctx.globalAlpha=.5;ctx.shadowBlur=22;ctx.shadowColor='#a99aff';ctx.fillStyle='#b8a4ff';ctx.beginPath();ctx.arc(0,0,p.r+3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#20243a';ctx.beginPath();ctx.arc(0,0,p.r-2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f3d9a0';ctx.beginPath();ctx.arc(p.faceX*5,p.faceY*5,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f2d8a0';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(p.faceX*8-p.faceY*6,p.faceY*8+p.faceX*6);ctx.lineTo(p.faceX*25-p.faceY*5,p.faceY*25+p.faceX*5);ctx.stroke();if(p.slash>0){ctx.strokeStyle='#d6c8ff';ctx.lineWidth=4;ctx.globalAlpha=p.slash/.4;ctx.beginPath();ctx.arc(0,0,36,-1.6,1.6);ctx.stroke()}ctx.restore();ctx.globalAlpha=1}
  function drawParticles(dt){for(const p of state.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.t-=dt;ctx.globalAlpha=clamp(p.t/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}state.particles=state.particles.filter(p=>p.t>0);ctx.globalAlpha=1;for(const f of state.floats){f.y-=22*dt;f.t-=dt;ctx.globalAlpha=clamp(f.t,0,1);ctx.font='bold 12px Manrope';ctx.textAlign='center';ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y)}state.floats=state.floats.filter(f=>f.t>0);ctx.globalAlpha=1}
  function render(dt){const p=state.player;state.camera.x=clamp(p.x-viewW/2,0,WORLD.w-viewW);state.camera.y=clamp(p.y-viewH/2,0,WORLD.h-viewH);if(window.Echoes3D){try{window.Echoes3D.render(state,dt);drawMinimap();return;}catch(err){console.error('3D scene failed; switching to the playable 2D fallback.',err);window.Echoes3D=null;const c=$('world3dCanvas');if(c)c.style.display='none';canvas.style.opacity='1';toast('3D renderer recovered · fallback mode');}}ctx.clearRect(0,0,viewW,viewH);ctx.save();ctx.translate(-state.camera.x,-state.camera.y);drawGround();drawNavigation();state.interactables.forEach(drawObject);state.enemies.forEach(drawEnemy);drawPlayer();drawParticles(dt);ctx.restore();const g=ctx.createRadialGradient(viewW/2,viewH/2,Math.min(viewW,viewH)*.2,viewW/2,viewH/2,Math.max(viewW,viewH)*.7);g.addColorStop(0,'#00000000');g.addColorStop(1,'#06081180');ctx.fillStyle=g;ctx.fillRect(0,0,viewW,viewH);drawMinimap()}
  function tick(now){const dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;state.tick+=dt;movePlayer(dt);if(state.player.pendingInteract){state.player.pendingInteract=false;interact()}updateEnemies(dt);nearestInteractable();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}if(Date.now()-state.lastSaved>15000)saveGame();if(Math.floor(state.tick)%2===0)updateTargetUI();render(dt);requestAnimationFrame(tick)}
  function keyDown(e){const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(k===' '){attack()}else if(k==='q'||k==='e'||k==='r'){useSkill(k)}else if(k==='f'||k==='enter'){interact()}else if(k==='tab'){e.preventDefault();pickTarget()}else if(k==='i'){openInventory()}else if(k==='k'){openSkills()}else if(k==='escape'){closeModal()}}
  window.addEventListener('keydown',keyDown);window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
  canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const rect=canvas.getBoundingClientRect();const x=clamp(e.clientX-rect.left+state.camera.x,35,WORLD.w-35),y=clamp(e.clientY-rect.top+state.camera.y,35,WORLD.h-35);let found=null,bd=Infinity;for(const en of state.enemies){if(!en.alive)continue;const d=Math.hypot(en.x-x,en.y-y);if(d<en.r+24&&d<bd){found=en;bd=d}}if(found){state.target=found;updateTargetUI();const d=dist(state.player,found);if(d> (state.className==='Paradoxist'?240:state.className==='Hollowkeeper'?165:95)){state.player.moveTarget={x:found.x,y:found.y};toast('MOVING TO TARGET · '+found.name.toUpperCase())}else attack();return}const obj=state.interactables.find(o=>Math.hypot(o.x-x,o.y-y)<o.r+10);if(obj){if(dist(state.player,obj)<obj.r+45)interact();else{state.player.moveTarget={x:obj.x,y:obj.y,interact:true};toast('MOVING TO · '+obj.name.toUpperCase())}return}state.player.moveTarget={x,y};particle(x,y,'#79d8db',8,70);toast('DESTINATION SET');});
  $('attackBtn').addEventListener('click',attack);document.querySelectorAll('.skill').forEach(b=>b.addEventListener('click',()=>useSkill(b.dataset.skill)));$('questFocus').addEventListener('click',()=>{syncQuestNavigation();const target=getQuestObjective();if(target){toast('TRACKING OBJECTIVE · '+target.name.toUpperCase());$('questObjectiveLine').textContent='TRACKING · '+target.name.toUpperCase()}else toast('CHAPTER MILESTONE COMPLETE');});
  $('inventoryBtn').addEventListener('click',openInventory);$('skillsBtn').addEventListener('click',openSkills);$('classBtn').addEventListener('click',openClassSelect);$('menuBtn').addEventListener('click',openMenu);$('modalClose').addEventListener('click',closeModal);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal()});$('clearLog').addEventListener('click',()=>{$('activityLog').innerHTML='';addLog('✦','Chronicle cleared','New echoes will appear here as you play.')});
  function openModal(title,eyebrow,html){$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;$('modalBackdrop').classList.remove('hidden')}
  function closeModal(){$('modalBackdrop').classList.add('hidden')}
  function openInventory(){let html='';if(!state.inventory.length)html='<p class="empty-state">Your pack is quiet. Defeat anomalies and search forgotten caches to find gear, relics, and crafting materials.</p>';else html='<div class="item-list">'+state.inventory.map((it,i)=>`<div class="item-row"><div class="item-icon">${it.icon||'◈'}</div><div><strong>${escapeHtml(it.name)}</strong><small>${escapeHtml(it.rarity||'Common')} · ${escapeHtml(it.type)}${it.damage?' · +'+it.damage+' ATK':''}${it.hp?' · +'+it.hp+' VIT':''}</small><p class="item-desc">${escapeHtml(it.description||'A relic of the unwritten world.')}</p></div>${['weapon','armor','relic'].includes(it.type)?`<button data-equip="${i}">${isEquipped(it)?'EQUIPPED':'EQUIP'}</button>`:''}</div>`).join('')+'</div>';html+='<p class="empty-state">Gear upgrades are persistent. Equipped items improve combat stats; shards are used by future crafting systems.</p>';openModal('Inventory','PERSONAL ARCHIVE',html);$('modalBody').querySelectorAll('[data-equip]').forEach(b=>b.addEventListener('click',()=>equipItem(Number(b.dataset.equip))))}
  function isEquipped(it){return Object.values(state.equipment).some(x=>x&&x.id===it.id)}
  function equipItem(i){const it=state.inventory[i];if(!it||!['weapon','armor','relic'].includes(it.type))return;const oldMax=state.maxHp,oldHp=state.hp;state.equipment[it.type]=it;statsForClass();state.hp=clamp(oldHp+(state.maxHp-oldMax),1,state.maxHp);updateUI();saveGame();openInventory();toast('EQUIPPED · '+it.name)}
  function openClassSelect(){const cards=Object.entries(classes).map(([name,c])=>`<div class="skill-node class-choice"><div class="glyph">${({Riftblade:'⚔',Paradoxist:'⌘',Hollowkeeper:'◈',Dawnbreaker:'✦'})[name]}</div><strong>${name}</strong><p>${c.desc}</p><small>${c.hp} VIT · ${c.mp} ESSENCE · ${c.damage} BASE ATK</small><button data-class="${name}">${state.className===name?'CURRENT CLASS':'CHOOSE CLASS'}</button></div>`).join('');openModal('Choose Your Class','CHARACTER FOUNDATION','<div class="skill-tree">'+cards+'</div><p class="empty-state">Changing class is free in this alpha. Gear remains equipped, but stats recalculate from the selected class and equipment.</p>');$('modalBody').querySelectorAll('[data-class]').forEach(b=>b.addEventListener('click',()=>{const previous=state.maxHp,previousHp=state.hp;state.skillBuilds=state.skillBuilds||{};state.skillBuilds[state.className]=state.skillRanks||defaultSkillRanks();state.className=b.dataset.class;state.skillRanks=Object.assign(defaultSkillRanks(),state.skillBuilds[state.className]||{});state.skillBuilds[state.className]=state.skillRanks;statsForClass();state.hp=clamp(previousHp+(state.maxHp-previous),1,state.maxHp);state.mp=clamp(state.mp,0,state.maxMp);updateUI();saveGame();openClassSelect();toast('CLASS SELECTED · '+state.className.toUpperCase())}))}
  function openSkills(){const book=classDisciplines[state.className]||classDisciplines.Riftblade;state.skillRanks=Object.assign(defaultSkillRanks(),state.skillRanks||{});state.skillBuilds=state.skillBuilds||{};state.skillBuilds[state.className]=state.skillRanks;const active=['q','e','r'].map(key=>{const sk=book[key],rank=state.skillRanks[key]||0;return `<article class="skill-node active-discipline"><div class="discipline-top"><span class="glyph">${sk.icon}</span><span class="rank-pill">RANK ${rank}/3</span></div><strong>${sk.name}</strong><p>${sk.desc}</p><small>${sk.cost} essence · ${sk.cd}s cooldown</small><div class="rank-track">${[1,2,3].map(n=>`<i class="${rank>=n?'filled':''}"></i>`).join('')}</div><p class="rank-next">${rank<3?'Next: '+sk.ranks[rank]:'MAX RANK · Discipline mastered'}</p><button data-upgrade="${key}" ${state.skillPoints<1||rank>=3||(rank===1&&state.level<3)||(rank===2&&state.level<5)?'disabled':''}>${rank>=3?'MASTERED':state.skillPoints<1?'NEED SKILL POINT':'UPGRADE · 1 POINT'}</button></article>`}).join('');const passives=book.passives.map((sk,i)=>{const rank=state.skillRanks[sk.id]||0;return `<article class="skill-node passive-discipline"><div class="discipline-top"><span class="glyph">${sk.icon}</span><span class="rank-pill">RANK ${rank}/1</span></div><strong>${sk.name}</strong><p>${sk.desc}</p><small>Unlocks at level ${sk.level}</small><p class="rank-next">${rank?'UNLOCKED · EFFECT ACTIVE':'Passive specialization'}</p><button data-upgrade="${sk.id}" ${rank||state.skillPoints<1||state.level<sk.level?'disabled':''}>${rank?'UNLOCKED':state.level<sk.level?'REQUIRES LEVEL '+sk.level:state.skillPoints<1?'NEED SKILL POINT':'UNLOCK · 1 POINT'}</button></article>`}).join('');const html=`<div class="skill-summary"><div><small>AVAILABLE SKILL POINTS</small><strong>${state.skillPoints||0}</strong></div><div><small>CHARACTER LEVEL</small><strong>${state.level}</strong></div><div><small>DISCIPLINE</small><strong>${escapeHtml(state.className)}</strong></div></div><p class="empty-state">Spend points to improve your three class abilities or unlock passive traits. Active ranks unlock at levels 1, 3, and 5. Passives unlock at levels 2, 4, and 6. Your build is saved automatically.</p><h3 class="tree-section-title">ACTIVE DISCIPLINES</h3><div class="skill-tree discipline-tree">${active}</div><h3 class="tree-section-title">CLASS PASSIVES</h3><div class="skill-tree passive-tree">${passives}</div><p class="empty-state">Respecialization: no respec fee in this milestone; spend points carefully or use the reset button below to refund skill ranks. This only resets skill choices, not character progress.</p><button id="refundSkills" class="refund-btn">REFUND ALL SKILL POINTS</button>`;openModal('Skill Tree & Specialization','CLASS PROGRESSION',html);$('modalBody').querySelectorAll('[data-upgrade]').forEach(b=>b.addEventListener('click',()=>upgradeSkill(b.dataset.upgrade)));$('refundSkills').addEventListener('click',()=>{const refund=Object.values(state.skillRanks).reduce((n,v)=>n+(Number(v)||0),0);state.skillPoints=(state.skillPoints||0)+refund;state.skillRanks=defaultSkillRanks();state.skillBuilds=state.skillBuilds||{};state.skillBuilds[state.className]=state.skillRanks;statsForClass();updateUI();saveGame();openSkills();toast('SKILL POINTS REFUNDED')})}
  function upgradeSkill(id){const book=classDisciplines[state.className]||classDisciplines.Riftblade;const ranks=state.skillRanks||defaultSkillRanks();if((state.skillPoints||0)<1){toast('NO SKILL POINTS AVAILABLE');return}if(['q','e','r'].includes(id)){const rank=ranks[id]||0;if(rank>=3){toast('DISCIPLINE ALREADY MASTERED');return}const required=rank===0?1:rank===1?3:5;if(state.level<required){toast('REQUIRES LEVEL '+required);return}ranks[id]=rank+1;}else{const passive=book.passives.find(p=>p.id===id);if(!passive||state.level<passive.level||ranks[id]){toast('PASSIVE NOT AVAILABLE');return}ranks[id]=1;}state.skillRanks=ranks;state.skillBuilds=state.skillBuilds||{};state.skillBuilds[state.className]=state.skillRanks;state.skillPoints--;statsForClass();updateUI();saveGame();openSkills();toast('DISCIPLINE UPGRADED · '+(book[id]?.name||book.passives.find(p=>p.id===id)?.name||id).toUpperCase());}
  function openMenu(){openModal('Chronicle Menu','ECHOES OF THE UNWRITTEN','<div class="menu-grid"><button id="menuInventory"><b>▤ Inventory</b><small>Review and equip found gear.</small></button><button id="menuSkills"><b>✧ Skills</b><small>Inspect active abilities.</small></button><button id="menuClass"><b>⚔ Class & Specialization</b><small>Choose your combat identity.</small></button><button id="menuSave"><b>◈ Save Chronicle</b><small>Store progress on this device.</small></button><button id="menuReset"><b>↻ New Chronicle</b><small>Start over from the beginning.</small></button></div><p class="empty-state">This build saves locally in this browser. Clearing site data or switching browsers may remove progress. Cloud accounts are not enabled in this prototype.</p>');$('menuInventory').onclick=()=>{closeModal();openInventory()};$('menuSkills').onclick=()=>{closeModal();openSkills()};$('menuClass').onclick=()=>{closeModal();openClassSelect()};$('menuSave').onclick=()=>{saveGame();toast('CHRONICLE SAVED');closeModal()};$('menuReset').onclick=()=>{if(confirm('Start a new chronicle? This will overwrite this device’s current save.')){localStorage.removeItem('echoes_unwritten_save_v1');resetNewGame();closeModal();openDialogue('The Archivist','The page is blank again. Good. It is easier to begin before the world remembers you.',()=>{})}}}
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  // The first encounter introduces the quest without interrupting movement.
  setTimeout(()=>{if(!state.flags.intro&&!state.flags.bossDefeated){state.flags.intro=true;openDialogue('The Archivist','If you can hear this, the fracture has already found you. Three echoes have scattered across the Verge. Bring them back, and I will show you the door the world tried to erase.',()=>{state.flags.archivist=true;addLog('✧','Quest accepted','A Voice in the Static — recover three lost echoes.');updateUI();saveGame()})}},900);
  applyEventUI();updateUI();requestAnimationFrame(tick);
  window.addEventListener('pagehide',saveGame);document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});
